import{_ as c,C as n,o as l,c as d,j as a,a as o,E as r,a2 as i}from"./chunks/framework.TaNiW7i8.js";const q=JSON.parse('{"title":"Chercher dans la mémoire","description":"","frontmatter":{"title":"Chercher dans la mémoire"},"headers":[],"relativePath":"agent/chercher.md","filePath":"agent/chercher.md"}'),u={name:"agent/chercher.md"};function m(h,e,p,g,f,v){const s=n("AskExample"),t=n("Ask");return l(),d("div",null,[e[0]||(e[0]=a("h1",{id:"chercher-dans-la-memoire",tabindex:"-1"},[o("Chercher dans la mémoire "),a("a",{class:"header-anchor",href:"#chercher-dans-la-memoire","aria-label":'Permalink to "Chercher dans la mémoire"'},"​")],-1)),e[1]||(e[1]=a("p",null,[o("Ce parcours sert à retrouver une décision, une note, ce que la mémoire sait d'un fichier, ou le fil des dernières sessions. Tout y est en "),a("strong",null,"lecture"),o(" : aucune recherche n'écrit dans la mémoire (sauf l'ajout d'alias, signalé plus bas).")],-1)),e[2]||(e[2]=a("h2",{id:"ce-que-vous-demandez-a-l-agent",tabindex:"-1"},[o("Ce que vous demandez à l'agent "),a("a",{class:"header-anchor",href:"#ce-que-vous-demandez-a-l-agent","aria-label":`Permalink to "Ce que vous demandez à l'agent"`},"​")],-1)),r(s,{tool:"mem_search"}),r(t,{say:"Cherche « scellé » dans les connaissances seulement, archives comprises.",verb:"mem_search",family:"rappel",args:'{"query":"scell","zone":"20-knowledge","include_archived":true}'}),r(s,{tool:"mem_about_path"}),r(t,{say:"Montre-moi ce qui est relié à la note 20-knowledge/runner, sur deux niveaux.",verb:"mem_relations",family:"rappel",args:'{"path":"20-knowledge/runner","depth":2}'}),r(s,{tool:"mem_digest"}),r(t,{say:"Ajoute à la note 20-knowledge/runner les mots « ça saccade sur téléphone ».",verb:"mem_alias_add",family:"structure",args:'{"path":"20-knowledge/runner","aliases":["ça saccade sur téléphone"]}'}),e[3]||(e[3]=i('<p>Une question sur le passé (« qu&#39;avait-on décidé sur… ? », « où a-t-on parlé de… ? ») suffit à ce que l&#39;agent cherche : les procédures livrées (voir <a href="/Kessho/agent/connecter.html">Connecter l&#39;agent</a>) l&#39;y invitent.</p><h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><ol><li><strong>Chercher du texte.</strong> <a href="/Kessho/reference/mcp/rappel.html#mem-search"><code>mem_search</code></a> cherche dans tout le vault et rend une correspondance par ligne, avec son contexte. Le motif <code>query</code> est une <strong>expression régulière</strong>. Les options, toutes facultatives : <ul><li><code>case_insensitive</code> : ignorer la casse (oui par défaut) ;</li><li><code>fold_accents</code> : « reglage » trouve « réglage » (oui par défaut) ;</li><li><code>fold_separators</code> : espaces, tirets et soulignés interchangeables, « deploy kit » trouve <code>deploy-kit</code> ; sans effet si le motif contient un métacaractère de regex (oui par défaut) ;</li><li><code>search_names</code> : le <strong>nom</strong> du fichier compte aussi, ces correspondances portent <code>line_number</code> 0 (oui par défaut) ;</li><li><code>zone</code> : se limiter à une zone (<code>00-inbox</code>, <code>10-episodes</code>, <code>20-knowledge</code>…) ;</li><li><code>include_archived</code> : inclure <code>10-episodes/archived/</code>, exclu par défaut ;</li><li><code>limit</code> : 50 correspondances par défaut, 500 au plus.</li></ul></li><li><strong>Savoir ce que la mémoire connaît d&#39;un fichier.</strong> <a href="/Kessho/reference/mcp/rappel.html#mem-about-path"><code>mem_about_path</code></a> prend le chemin d&#39;un fichier du <strong>dépôt de code</strong>, <strong>relatif</strong> à sa racine (un chemin absolu est refusé), et rend ce que le vault en sait : les faits de la carte qui le décrivent, le manifeste qui a établi sa technologie, le document de cadrage qui le concerne. Le catalogue demande de l&#39;appeler <strong>avant</strong> de toucher un fichier qu&#39;on ne connaît pas. Ne rien savoir n&#39;est pas une erreur : la réponse dit alors combien de notes citent un fichier quelconque.</li><li><strong>Suivre les liens d&#39;une note.</strong> <a href="/Kessho/reference/mcp/rappel.html#mem-relations"><code>mem_relations</code></a> prend le chemin d&#39;une note (relatif au vault, avec ou sans <code>.md</code>) et rend ce qui est plus général (<code>up</code>), plus précis (<code>down</code>) et voisin (<code>side</code>). <code>direction</code> vaut <code>up</code>, <code>down</code>, <code>side</code> ou <code>all</code> (défaut) ; <code>depth</code> va de 1 à 6 (défaut 2). Au-delà de 200 notes, le résultat est marqué tronqué ; les liens dont la cible n&#39;existe pas sont nommés.</li><li><strong>Le fil des sessions.</strong> <a href="/Kessho/reference/mcp/rappel.html#mem-digest"><code>mem_digest</code></a> résume les <code>n</code> archives les plus récentes d&#39;un projet (5 par défaut, 50 au plus) : date, sujet, extrait. Un projet archivé n&#39;est résumé qu&#39;avec <code>from_archived: true</code>. Pour lire une archive entière, voir <a href="/Kessho/reference/mcp/rappel.html#mem-read-archive"><code>mem_read_archive</code></a> dans <a href="/Kessho/agent/reprendre.html">Reprendre un projet</a>.</li><li><strong>Le graphe entier.</strong> <a href="/Kessho/reference/mcp/rappel.html#mem-graph-export"><code>mem_graph_export</code></a> exporte les notes et leurs relations ; la charge est volumineuse, <code>levels</code> ne garde que les niveaux demandés (<code>domaine</code>, <code>concept</code>, <code>projet</code>, <code>note</code>, <code>archive</code>).</li><li><strong>Aider à retrouver.</strong> <a href="/Kessho/reference/mcp/structure.html#mem-alias-add"><code>mem_alias_add</code></a> <strong>écrit</strong> : il ajoute à une note des alias en langue de tous les jours (le symptôme, le besoin) pour qu&#39;on la retrouve avec ces mots. Les alias déjà présents ne sont jamais perdus.</li></ol><h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>Une recherche d&#39;agent ne change rien à l&#39;écran : le résultat est dans la conversation avec votre agent. L&#39;application a ses propres moyens de retrouver une note : <strong>Chercher</strong> dans la barre latérale (voir <a href="/Kessho/guide/home.html">Accueil</a>) et le <a href="/Kessho/guide/graph.html">graphe</a>.</p><p>Seul <code>mem_alias_add</code> écrit : il allume le témoin de fraîcheur comme toute écriture d&#39;agent (voir <a href="/Kessho/guide/zones.html">Zones</a>).</p>',6))])}const b=c(u,[["render",m]]);export{q as __pageData,b as default};
